<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$rows=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'create');if($action==='create'){$code=strtoupper(trim((string)$_POST['template_code']));$channel=(string)$_POST['channel'];$name=trim((string)$_POST['template_name']);$category=trim((string)$_POST['category']);$subject=trim((string)($_POST['subject_template']??''));$body=trim((string)$_POST['body_template']);if(!preg_match('/^[A-Z0-9_]{3,100}$/',$code)||!in_array($channel,['email','whatsapp','sms'],true)||$name===''||$body==='')throw new RuntimeException('Valid template code, channel, name and body are required.');$s=$pdo->prepare("INSERT INTO communication_templates(organization_id,template_code,channel,template_name,category,subject_template,body_template,is_system,is_active) VALUES(?,?,?,?,?,?,?,0,1)");$s->execute([$orgId,$code,$channel,$name,$category?:'general',$subject?:null,$body]);$msg='Custom template created.';}elseif($action==='toggle'){$id=(int)$_POST['id'];$s=$pdo->prepare("UPDATE communication_templates SET is_active=1-is_active WHERE organization_id=? AND id=? AND is_system=0");$s->execute([$orgId,$id]);$msg='Custom template status updated.';}}$s=$pdo->prepare("SELECT * FROM communication_templates WHERE organization_id=? ORDER BY is_system DESC,channel,template_name");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication Templates - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Communication Templates</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_rules.php">Rules</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1320px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • TEMPLATES</div><h1>Reusable, non-sensitive communication templates.</h1><p>System templates are immutable baselines. Custom templates are versioned by new records/status rather than deleting historical Outbox snapshots.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=comm_step21_h($msg)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><h2>Create Custom Template</h2><form method="post" class="pp-form"><input type="hidden" name="action" value="create"><div class="pp-grid"><label class="pp-field pp-span-3"><span>Template Code</span><input name="template_code" maxlength="100" placeholder="CUSTOM_FOLLOWUP" required></label><label class="pp-field pp-span-3"><span>Channel</span><select name="channel"><option>email</option><option>whatsapp</option><option>sms</option></select></label><label class="pp-field pp-span-3"><span>Name</span><input name="template_name" maxlength="190" required></label><label class="pp-field pp-span-3"><span>Category</span><input name="category" maxlength="60" value="general"></label><label class="pp-field pp-span-12"><span>Subject (Email only)</span><input name="subject_template" maxlength="255" placeholder="Hello {{name}}"></label><label class="pp-field pp-span-12"><span>Body</span><textarea name="body_template" rows="5" required placeholder="Hello {{name}}, {{message}}"></textarea></label></div><button class="os-btn primary">Create Template</button></form></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Template Library</h2><p>Supported placeholders: {{name}}, {{message}}, {{reference}}, {{date}}, {{amount}}.</p></div><span class="pp-badge"><?=count($rows)?> templates</span></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Code</th><th>Channel</th><th>Name</th><th>Preview</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=comm_step21_h($r['template_code'])?></b><br><small><?=comm_step21_h($r['category'])?></small></td><td><?=comm_step21_h(strtoupper((string)$r['channel']))?></td><td><?=comm_step21_h($r['template_name'])?><br><small><?=$r['is_system']?'System baseline':'Custom'?></small></td><td><?php if($r['subject_template']):?><b><?=comm_step21_h($r['subject_template'])?></b><br><?php endif;?><small><?=comm_step21_h(strlen((string)$r['body_template'])>180?substr((string)$r['body_template'],0,180).'…':$r['body_template'])?></small></td><td><span class="pp-badge <?=((int)$r['is_active']===1)?'':'warn'?>"><?=((int)$r['is_active']===1)?'ACTIVE':'INACTIVE'?></span></td><td><?php if(!(int)$r['is_system']):?><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="os-btn"><?=((int)$r['is_active']===1)?'Disable':'Enable'?></button></form><?php else:?><small>Protected</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
